65 // ---------------------------------------------------------------------------------
75 // ---------------------------------------------------------------------------------
76 #if defined(_MSC_VER) && _MSC_VER < 1900
77 
78 inline int c99_ai_vsnprintf(char *outBuf, size_t size, const char *format, va_list ap) {
79     int count(-1);
80     if (0 != size) {
81         count = _vsnprintf_s(outBuf, size, _TRUNCATE, format, ap);
82     }
83     if (count == -1) {
84         count = _vscprintf(format, ap);
85     }
86 
87     return count;
88 }
89 
90 inline int ai_snprintf(char *outBuf, size_t size, const char *format, ...) {
91     int count;
92     va_list ap;
93 
94     va_start(ap, format);
95     count = c99_ai_vsnprintf(outBuf, size, format, ap);
96     va_end(ap);
97 
98     return count;
99 }
100 
101 #elif defined(__MINGW32__)
102 #define ai_snprintf __mingw_snprintf
103 #else
104 #define ai_snprintf snprintf
105 #endif
